import sys

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        cur = self.root
        for ch in word:
            if ch not in cur.children:
                cur.children[ch] = TrieNode()
            cur = cur.children[ch]
        cur.is_end = True

    def search(self, word: str) -> bool:
        cur = self.root
        for ch in word:
            if ch not in cur.children:
                return False
            cur = cur.children[ch]
        return cur.is_end

    def starts_with(self, prefix: str) -> bool:
        cur = self.root
        for ch in prefix:
            if ch not in cur.children:
                return False
            cur = cur.children[ch]
        return True

def solve():
    raw = sys.stdin.read().split()
    if not raw:
        return
    Q = int(raw[0])
    idx = 1
    trie = Trie()
    out = []

    for _ in range(Q):
        op = int(raw[idx])
        arg = raw[idx+1]
        idx += 2

        if op == 1:
            trie.insert(arg)
        elif op == 2:
            out.append("true" if trie.search(arg) else "false")
        elif op == 3:
            out.append("true" if trie.starts_with(arg) else "false")

    sys.stdout.write('\n'.join(out) + '\n')

if __name__ == '__main__':
    solve()

